package mz.bam.seeky.android;
import android.content.Context;import android.graphics.*;import android.view.*;
/** Drag a new rectangle on the visible reader snapshot; coordinates mapped to source pixels. */
final class CropView extends View {
 final Bitmap bitmap;final Paint paint=new Paint(3);final RectF image=new RectF(),selection=new RectF();float downX,downY;boolean chosen;
 CropView(Context c,Bitmap b){super(c);bitmap=b;setContentDescription("Arraste para seleccionar a área do recorte.");}
 protected void onMeasure(int w,int h){int width=MeasureSpec.getSize(w);setMeasuredDimension(width,Math.max(getMinimumHeight(),Math.min((int)(width*1.3f),getResources().getDisplayMetrics().heightPixels/2)));}
 protected void onSizeChanged(int w,int h,int ow,int oh){float scale=Math.min(w/(float)bitmap.getWidth(),h/(float)bitmap.getHeight());float iw=bitmap.getWidth()*scale,ih=bitmap.getHeight()*scale;image.set((w-iw)/2,(h-ih)/2,(w+iw)/2,(h+ih)/2);selection.set(image);chosen=false;}
 protected void onDraw(Canvas c){c.drawColor(0xffece9f3);c.drawBitmap(bitmap,null,image,paint);paint.setColor(0x88000000);c.drawRect(image.left,image.top,image.right,selection.top,paint);c.drawRect(image.left,selection.bottom,image.right,image.bottom,paint);c.drawRect(image.left,selection.top,selection.left,selection.bottom,paint);c.drawRect(selection.right,selection.top,image.right,selection.bottom,paint);paint.setColor(0xff8051d2);paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(3*getResources().getDisplayMetrics().density);c.drawRect(selection,paint);paint.setStyle(Paint.Style.FILL);}
 float x(float n){return Math.max(image.left,Math.min(image.right,n));}float y(float n){return Math.max(image.top,Math.min(image.bottom,n));}
 public boolean onTouchEvent(MotionEvent e){if(e.getActionMasked()==MotionEvent.ACTION_DOWN){getParent().requestDisallowInterceptTouchEvent(true);downX=x(e.getX());downY=y(e.getY());selection.set(downX,downY,downX,downY);chosen=true;invalidate();return true;}if(e.getActionMasked()==MotionEvent.ACTION_MOVE||e.getActionMasked()==MotionEvent.ACTION_UP){selection.set(Math.min(downX,x(e.getX())),Math.min(downY,y(e.getY())),Math.max(downX,x(e.getX())),Math.max(downY,y(e.getY())));if(e.getActionMasked()==MotionEvent.ACTION_UP){if(selection.width()<8||selection.height()<8){selection.set(image);chosen=false;}performClick();getParent().requestDisallowInterceptTouchEvent(false);}invalidate();return true;}if(e.getActionMasked()==MotionEvent.ACTION_CANCEL){selection.set(image);getParent().requestDisallowInterceptTouchEvent(false);invalidate();return true;}return true;}
 public boolean performClick(){super.performClick();return true;}
 Bitmap crop(){float factor=bitmap.getWidth()/image.width();int l=Math.max(0,(int)((selection.left-image.left)*factor)),t=Math.max(0,(int)((selection.top-image.top)*factor));int r=Math.min(bitmap.getWidth(),(int)Math.ceil((selection.right-image.left)*factor)),b=Math.min(bitmap.getHeight(),(int)Math.ceil((selection.bottom-image.top)*factor));return Bitmap.createBitmap(bitmap,l,t,Math.max(1,r-l),Math.max(1,b-t));}
}
